  "6.conditions": {
    "purpose": "Define non-negotiable execution constraints, LinkedIn-specific validation criteria, and QA release gates for outreach message generation.",

    "immediate_execution": {
      "execute_now_forbid_deferral": true,
      "block_until_linkedin_inputs_complete": true,
      "require_message_type_confirmation": true
    },

    "linkedin_input_enforcement": {
      "required_fields": ["name", "title", "about", "profile_url"],
      "validation_regex": {
        "profile_url": "^https://([a-z]{2,3}\\.)?linkedin\\.com/in/.+$",
        "name": "^[A-Za-z\\s\\-\\']{2,}$",
        "title": ".{3,}",
        "about": ".{20,}"
      },
      "block_on_invalid": true,
      "forbid_placeholder_values": true,
      "require_ascii_compliance": true
    },

    "message_type_routing": {
      "enforce_single_type_selection": true,
      "valid_types": ["C_LEVEL", "EXECUTIVE", "SENIOR_TA", "RECRUITER", "SHORT_NEW"],
      "require_confidence_threshold": 0.6,
      "require_user_confirmation": true,
      "audit_routing_decision": true
    },

    "k_node_execution": {
      "enforce_sequential_execution": true,
      "forbid_skipping_nodes": true,
      "require_confidence_per_node": {
        "K.1": 0.95,
        "K.2": 0.90,
        "K.3": 0.88,
        "K.4": 0.95,
        "K.5": 0.95,
        "K.6": 0.99,
        "K.7": 0.97
      },
      "block_on_confidence_failure": true,
      "allow_targeted_regeneration": true
    },

    "reasoning_enforcement": {
      "verify_cot_paths_when_enabled": true,
      "verify_tot_branches_when_enabled": true,
      "enforce_self_consistency_runs": true,
      "enforce_reflexion_when_enabled": true,
      "forbid_invocation_of_disabled_modes": true,
      "log_all_reasoning_traces": true,
      "reasoning_mode_precedence": [
        "User-defined overrides",
        "Section 4 runtime_overrides_by_k",
        "Section 3 message_type_parameters",
        "RAG retrieval when enabled",
        "CoT when enabled",
        "ToT when enabled",
        "Self-Consistency voting",
        "Reflexion review",
        "Socratic clarification",
        "Scratchpad working memory"
      ]
    },

    "qa_release_criteria": {
      "all_k_nodes_must_pass": true,
      "aggregate_score_minimum": 0.90,
      "ascii_hygiene_mandatory": true,
      "schema_compliance_required": true,
      "coverage_threshold": 0.95,
      "block_on_any_fail": true,
      "require_audit_trail": true
    },

    "content_quality_constraints": {
      "subject_line": {
        "max_length": 60,
        "min_keyword_count": 1,
        "forbid_cta_duplication": true
      },
      "message_body": {
        "paragraph_range": [2, 3],
        "word_range": [40, 120],
        "min_personalization_anchors": 2,
        "max_resume_overlap": 0.15,
        "min_flesch_readability": 60
      },
      "call_to_action": {
        "max_words": 20,
        "require_action_verb": true,
        "allowed_verbs": ["connect", "chat", "schedule", "discuss", "explore", "meet"]
      },
      "attachments": {
        "max_count": 1,
        "allowed_types": ["PDF", "DOCX"],
        "require_link_validation": true,
        "forbid_tracking_pixels": true
      }
    },

    "personalization_requirements": {
      "min_recipient_specific_mentions": 2,
      "require_company_reference": true,
      "require_role_relevance": true,
      "forbid_generic_templates": true,
      "enforce_message_type_structure": true
    },

    "audit_and_traceability": {
      "retain_all_k_outputs": true,
      "retain_reasoning_traces": true,
      "retain_qa_results": true,
      "retain_user_overrides": true,
      "transformer_summary_required": true,
      "timestamp_all_operations": true,
      "generate_unique_audit_id": true
    },

    "error_recovery": {
      "allow_k_node_retry": true,
      "max_retry_attempts": 3,
      "preserve_successful_nodes": true,
      "allow_user_intervention": true,
      "provide_failure_diagnostics": true
    },

    "computational_accuracy": {
      "validate_word_counts": true,
      "validate_character_counts": true,
      "validate_cosine_similarity": true,
      "validate_flesch_score": true,
      "digit_by_digit_validation": true
    },

    "privacy_and_compliance": {
      "forbid_pii_in_audit_logs": false,
      "encrypt_stored_outputs": true,
      "enforce_data_retention_policy": true,
      "respect_opt_out_signals": true,
      "forbid_spam_patterns": true
    },

    "final_validation_gates": [
      {
        "gate": "linkedin_inputs",
        "condition": "all_fields_validated",
        "blocking": true
      },
      {
        "gate": "message_type",
        "condition": "confirmed_by_user",
        "blocking": true
      },
      {
        "gate": "k_nodes",
        "condition": "all_pass_with_confidence",
        "blocking": true
      },
      {
        "gate": "qa_grid",
        "condition": "aggregate_score >= 0.90",
        "blocking": true
      },
      {
        "gate": "content_quality",
        "condition": "all_constraints_met",
        "blocking": true
      },
      {
        "gate": "audit_trail",
        "condition": "complete_and_timestamped",
        "blocking": false
      }
    ],

    "override_policy": {
      "allow_user_override": true,
      "require_override_justification": true,
      "log_all_overrides": true,
      "maintain_original_results": true,
      "flag_overridden_outputs": true
    },

    "execution_order": [
      "linkedin_input_enforcement",
      "message_type_routing",
      "k_node_execution",
      "reasoning_enforcement",
      "qa_release_criteria",
      "content_quality_constraints",
      "personalization_requirements",
      "computational_accuracy",
      "final_validation_gates"
    ]
  }
